# PTX source for a dummy scaled‑dot‑product‑attention kernel (fp16 copy)
PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

.visible .entry sdp_attention_kernel(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 Out_ptr,
    .param .u32 B,
    .param .u32 H,
    .param .u32 S,
    .param .u32 D
)
{
    // ------------------------------------------------------------
    // Thread/block indexing
    // ------------------------------------------------------------
    .reg .u32   %r<12>;
    .reg .u64   %rd<12>;

    // blockIdx.x encodes (batch, head)
    ld.param.u32   %r0, [B];          // B
    ld.param.u32   %r1, [H];          // H
    ld.param.u32   %r2, [S];          // S
    ld.param.u32   %r3, [D];          // D

    mov.u32        %r4, %ctaid.x;    // bh_index = blockIdx.x
    mov.u32        %r5, %ctaid.y;    // unused
    mov.u32        %r6, %ctaid.z;    // unused

    // b = bh_index / H
    // h = bh_index % H
    div.u32        %r7, %r4, %r1;    // b
    mul.lo.u32     %r8, %r7, %r1;    // b*H
    sub.u32        %r9, %r4, %r8;    // h

    // thread index within the block processes elements along S (sequence)
    mov.u32        %r10, %tid.x;     // i (position in sequence)

    // ------------------------------------------------------------
    // Compute linear offsets
    // ------------------------------------------------------------
    // offset = ((b * H + h) * S + i) * D
    mul.lo.u32     %r11, %r7, %r1;          // b*H
    add.u32        %r11, %r11, %r9;         // b*H + h
    mul.lo.u32     %r11, %r11, %r2;         // (b*H+h)*S
    add.u32        %r11, %r11, %r10;        // (b*H+h)*S + i
    mul.lo.u64     %rd1, %r11, %r3;         // *D  (in elements)

    // Convert element offset to byte offset (fp16 = 2 bytes)
    mul.lo.u64     %rd2, %rd1, 2;           // byte offset

    // Load base pointers
    ld.param.u64   %rd3, [Q_ptr];
    ld.param.u64   %rd4, [Out_ptr];

    // Compute final addresses
    add.u64        %rd5, %rd3, %rd2;   // Q + offset
    add.u64        %rd6, %rd4, %rd2;   // Out + offset

    // Guard against out‑of‑range threads
    setp.ge.u32    %p0, %r10, %r2;    // if i >= S -> mask
    @%p0 bra       DONE;

    // ------------------------------------------------------------
    // Copy D fp16 elements from Q to Out
    // ------------------------------------------------------------
    .reg .pred   %p1;
    .reg .u32    %r12;
    .reg .f16    %f1, %f2;

    mov.u32       %r12, 0;           // d index

COPY_LOOP:
    setp.ge.u32   %p1, %r12, %r3;    // if d >= D break
    @%p1 bra      END_COPY;

    // Load one fp16 element
    ld.global.f16 %f1, [%rd5 + %r12*2];
    // Store to output
    st.global.f16 [%rd6 + %r12*2], %f1;

    add.u32       %r12, %r12, 1;
    bra.uni       COPY_LOOP;

END_COPY:
DONE:
    ret;
}
"""

