        # Load PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, Q, K, V):
        # Determine launch configuration
        batch, heads, seq_len, embed_dim = Q.shape
        grid = (batch * heads, 1, 1)          # one block per (batch, head)
        block = (32, 1, 1)                    # 32 threads per block (covers seq_len)

        # Prepare argument list (pointers are assumed to be already device pointers)
        args = [
            Q.data_ptr(),   # Q_ptr
            K.data_ptr(),   # K_ptr (unused)
            V.data_ptr(),   # V_ptr (unused)
            Q.data_ptr(),   # Out_ptr (in‑place copy for demo)
            batch,
            heads,
            seq_len,
            embed_dim
        ]

        # Launch kernel
        ptx_launch(self.module, "sdp_attention_kernel", grid, block, args)

